struct SalaryHistory {
    private var byStart: [(start: Date, value: Money)] = []   // kept sorted by start
    func value(at when: Date) -> Money? {
        var lo = 0, hi = byStart.count                        // first index with start > when
        while lo < hi {
            let mid = (lo + hi) / 2
            if byStart[mid].start <= when { lo = mid + 1 } else { hi = mid }
        }
        return lo == 0 ? nil : byStart[lo - 1].value          // latest milestone <= when
    }
    // put: insert at the first index with start > from; the default form reads Date() once
}
